/* ============================================================
   PATCH v1.3.3 — принудительный показ гипотез
   ============================================================ */
#taskModal #hypTreeGroup {
    display: block !important;
    grid-column: 1 / -1 !important;
    width: 100% !important;
    margin-top: 12px !important;
    padding: 12px 14px !important;
    background: var(--trk-hover-row, rgba(255,255,255,0.03)) !important;
    border: 1px solid var(--trk-card-border, rgba(245,215,110,0.18)) !important;
    border-radius: 12px !important;
    box-sizing: border-box !important;
}
#taskModal #hypTreeGroup[hidden] {
    display: block !important;
}
#taskModal #hypTreeList {
    display: grid !important;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr)) !important;
    gap: 10px !important;
    align-items: start !important;
}
@media (max-width: 820px) {
    #taskModal #hypTreeList {
        grid-template-columns: 1fr !important;
    }
}
#taskModal #taskAssigneesList {
    max-height: 220px !important;
    min-height: 140px !important;
}

/* ============================================================
   PATCH v1.3.3 — АБСОЛЮТНАЯ страховка гипотез
   ============================================================ */
(function(){
    if (window.__trkHypAbsoluteV133) return;
    window.__trkHypAbsoluteV133 = true;

    function forceShow() {
        var m = document.getElementById('taskModal');
        if (!m) return;
        var hg = document.getElementById('hypTreeGroup');
        if (!hg) return;

        // Принудительно показываем
        hg.hidden = false;
        hg.removeAttribute('hidden');
        hg.style.display = 'block';
        hg.style.visibility = 'visible';
        hg.classList.add('trk-hyp-fullwidth');

        // Пихаем в конец сетки, если она есть
        var grid = m.querySelector('.task-modal-grid');
        if (grid && hg.parentNode !== grid) {
            grid.appendChild(hg);
        }
    }

    // 1. Наблюдатель за открытием модалки
    var tm = document.getElementById('taskModal');
    if (tm && !tm._hypV133Obs) {
        tm._hypV133Obs = true;
        new MutationObserver(function(){
            if (tm.classList.contains('active')) {
                setTimeout(forceShow, 50);
                setTimeout(forceShow, 200);
                setTimeout(forceShow, 500);
                setTimeout(forceShow, 1000);
            }
        }).observe(tm, { attributes: true, attributeFilter: ['class'] });
    }

    // 2. Перебиваем openTaskModal, чтобы даже если старый код её скрывает, мы сразу вернули
    if (typeof window.__trkOpenTaskModal === 'function' && !window.__trkOpenTaskModal._hypV133) {
        var origOpen = window.__trkOpenTaskModal;
        window.__trkOpenTaskModal = function(t) {
            var r = origOpen.apply(this, arguments);
            setTimeout(forceShow, 10);
            setTimeout(forceShow, 100);
            setTimeout(forceShow, 300);
            return r;
        };
        window.__trkOpenTaskModal._hypV133 = true;
    }
})();
